<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$done=in_array($appointment['status'],['cancelled','completed','no_show'],true);$labels=['confirmed'=>'Confirmado','pending'=>'Pendente','completed'=>'Concluído','cancelled'=>'Cancelado','no_show'=>'Não compareceu']; ?>
<main class="customer-selfservice"><header><span class="eyebrow">Seu agendamento</span><div class="selfservice-check">✓</div><h1><?=($appointment['status']==='cancelled')?'Agendamento cancelado':'Tudo certo para o seu atendimento'?></h1><p><?=$e($appointment['tenant_name'])?></p></header><?php if($message):?><div class="alert alert-success"><?=$e($message)?></div><?php endif;?><section class="selfservice-ticket"><div class="ticket-date"><strong><?=date('d',strtotime($appointment['starts_at']))?></strong><span><?=mb_strtoupper(date('M',strtotime($appointment['starts_at'])))?></span></div><div class="ticket-main"><h2><?=$e($appointment['service_name'])?></h2><p><?=date('d/m/Y',strtotime($appointment['starts_at']))?> às <strong><?=date('H:i',strtotime($appointment['starts_at']))?></strong></p><small>Profissional: <?=$e($appointment['professional_name']??'a definir')?></small></div><span class="badge text-bg-<?=in_array($appointment['status'],['confirmed','completed'],true)?'success':($appointment['status']==='cancelled'?'secondary':'warning')?>"><?=$e($labels[$appointment['status']]??$appointment['status'])?></span></section><section class="selfservice-actions"><?php if(!$done):?><form method="post" action="/booking/<?=$e($token)?>/confirm"><?=\App\Core\CSRF::field()?><button class="btn btn-success btn-lg">Confirmar presença</button></form><?php if($settings['customer_can_reschedule']):?><a class="btn btn-outline-primary btn-lg" href="/booking/<?=$e($token)?>/reschedule">Escolher outro horário</a><?php endif;?><?php if($settings['customer_can_cancel']):?><form method="post" action="/booking/<?=$e($token)?>/cancel" onsubmit="return confirm('Tem certeza que deseja cancelar este agendamento?')"><?=\App\Core\CSRF::field()?><button class="btn btn-link text-danger">Cancelar agendamento</button></form><?php endif;?><?php endif;?><a class="btn btn-light" href="/a/<?=$e($appointment['public_short_code']?:$appointment['public_slug'])?>">Ver página do estabelecimento</a></section><p class="selfservice-help">Guarde este link. Por ele você pode consultar, confirmar ou alterar o agendamento.</p></main>
